rules = cells('Rules', 'B30:D39')
leaf_costs = dict(cells('Leaf costs', 'E30:F32'))

def get_costs(part):
    if part in leaf_costs:
        return {part: leaf_costs[part]}
    sub = {}
    for p, c, mult in rules:
        if p == part:
            sc = get_costs(c)
            for sp, scost in sc.items():
                sub[sp] = sub.get(sp, 0) + scost * mult
    return sub

def total_cost(part):
    return sum(get_costs(part).values())

result = round(total_cost('Crate') - total_cost('Beacon'), 2)

